	Handler string
	Enabled bool
}

// Resolve returns the handler for the most specific enabled prefix.
// BUG: /api matches before /api/admin and disabled routes can still win.
func Resolve(routes []Route, path string) (string, bool) {
	var handler string
	found := false
	bestLen := -1
	for _, route := range routes {
		if !route.Enabled {
			continue
		}
		prefix := route.Prefix
		if len(prefix) > len(path) {
			continue
		}
		if path[:len(prefix)] != prefix {
			continue
		}
		// The match must end on a path segment boundary so that
		// "/api" does not match "/api-admin".
		if len(prefix) != len(path) && path[len(prefix)] != '/' {
			continue
		}
		if len(prefix) > bestLen {
			bestLen = len(prefix)
			handler = route.Handler
			found = true
		}
	}
	return handler, found
}

